package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;
public final class CardBrowserOverlay{private CardBrowserOverlay(){}public static void install(Activity a){if(!(a instanceof CreditCardsActivity))return;View root=a.findViewById(android.R.id.content);if(root!=null)root.post(()->inject(a,root));}static void inject(Activity a,View root){if(root.findViewWithTag("card_month_browser")!=null)return;ViewGroup c=(ViewGroup)root;if(c.getChildCount()==0||!(c.getChildAt(0) instanceof LinearLayout))return;LinearLayout r=(LinearLayout)c.getChildAt(0);Button b=new Button(a);b.setTag("card_month_browser");b.setText("Historial, meses y simulación");b.setAllCaps(false);b.setOnClickListener(v->a.startActivity(new Intent(a,CardBrowserActivity.class)));r.addView(b,Math.min(2,r.getChildCount()),new LinearLayout.LayoutParams(-1,-2));}}
